var config = new ProducerConfig
{
    BootstrapServers = "broker-1:9092",
    TransactionalId = "payment-processor-tx" // Unique per transactional producer
};

using var producer = new ProducerBuilder<string, string>(config).Build();
producer.InitTransactions(TimeSpan.FromSeconds(10));

try
{
    producer.BeginTransaction();

    await producer.ProduceAsync("payments", new Message<string, string>
    {
        Key = "tx-1",
        Value = "Processed payment for order 1"
    });

    await producer.ProduceAsync("audit", new Message<string, string>
    {
        Key = "tx-1",
        Value = "Audit: payment 1 processed at " + DateTime.UtcNow
    });

    producer.CommitTransaction();
}
catch (Exception)
{
    producer.AbortTransaction();
    throw;
}

const { Kafka } = require('kafkajs');

const kafka = new Kafka({ clientId: 'tx-consumer', brokers: ['localhost:9092'] });
const consumer = kafka.consumer({ groupId: 'read-committed-group' });
const producer = kafka.producer({ transactionalId: 'tx-consumer-prod' });

async function run() {
  await consumer.connect();
  await producer.connect();
  await producer.initTransactions();

  await consumer.subscribe({ topic: 'input-topic', fromBeginning: true });

  await consumer.run({
    eachMessage: async ({ message }) => {
      await producer.beginTransaction();

      try {
        const processed = transform(message.value.toString());
        await producer.send({ topic: 'output-topic', messages: [{ value: processed }] });
        await producer.commitTransaction();
      } catch (err) {
        await producer.abortTransaction();
        throw err;
      }
    }
  });
}

run();
